import { createToken } from '@shared/application/di/token';

/**
 * Attribution of the built-in library for Settings → Credits (S1-24). Registered by the
 * composition root from `ExerciseSeedSource.manifest.source`, so the dataset name, link and licence
 * exist once, next to the seed (generated by `tooling/exercise-db` from `pin.js`).
 */
export interface ExerciseDataCredits {
  /** "free-exercise-db" */
  readonly datasetName: string;
  readonly repositoryUrl: string;
  /** "The Unlicense (public domain)" */
  readonly licenceName: string;
  readonly licenceUrl: string;
}

export const ExerciseDataCreditsToken = createToken<ExerciseDataCredits>(
  'exercises.ExerciseDataCredits',
);
